def _invmod(a,n):
    a%=n
    g,x,y=_egcd(a,n)
    if g!=1:
        return None
    return x%n

def _order_10(n):
    # assumes gcd(n,10)=1
    val=1%n
    for k in range(1, n+1):
        val=(val*10)%n
        if val==1:
            return k
    return None

def _pow10_map(n, ord10):
    mp={1:0}
    val=1%n
    for d in range(1, ord10):
        val=(val*10)%n
        if val in mp:
            # should not happen before ord10 if ord10 correct
            break
        mp[val]=d
    return mp

def _block_window_residues(n, Bstr):
    L=len(Bstr)
    Q=int(Bstr)
    base=10**L
    lo=(Q*n + base - 1)//base
    hi=((Q+1)*n - 1)//base
    lo=max(1, lo)
    hi=min(n-1, hi)
    if lo>hi:
        return []
    out=[]
    for r in range(lo, hi+1):
        if math.gcd(r,n)==1:
            out.append(r)
    return out

def _min_n_for_instance(P, Q, t1, r1, t2, r2, NMAX=6000):
    # search n increasing
    for n in range(3, NMAX+1):
        if math.gcd(n,10)!=1:
            continue
        ord10=_order_10(n)
        if not ord10:
            continue
