        # candidate remainders starting a block equal to P or Q
        SP=_block_window_residues(n, P)
        SQ=_block_window_residues(n, Q)
        if not SP or not SQ:
            continue
        g_all=math.gcd(ord10, math.gcd(t1, t2))
        # Try to find compatible pair (rP, rQ)
        for rP in SP:
            for rQ in SQ:
                inv_rQ=_invmod(rQ, n)
                if inv_rQ is None:
                    continue
                ratio=(rP*inv_rQ)%n
                d=mp.get(ratio, None)
                if d is None:
